/**
 * The contract `badge.tsx` (native) and `badge.web.tsx` (web) both implement.
 * Its own module because Metro resolves `./badge` to `badge.web.tsx` on web.
 *
 * The variant names are shadcn's six — `default`, `secondary`, `destructive`,
 * `outline`, `ghost`, `link` — with their meanings, plus `success` and `warning`,
 * which the shadcn token set has no answer for (see `badge.tsx`'s header).
 *
 * The web half also takes every `<span>` attribute (`style`, `title`, `onClick`,
 * `data-*`) and shadcn's `asChild`, so a DOM call site ports unchanged. Those
 * extras are web only.
 */
import { cva } from "class-variance-authority";
import { Children, type ReactNode } from "react";

export type BadgeVariant =
  | "default"
  | "secondary"
  | "destructive"
  | "outline"
  | "ghost"
  | "link"
  | "success"
  | "warning";

export type BadgeProps = {
  variant?: BadgeVariant | undefined;
  /**
   * Overrides the variant's background with a literal colour — for a badge
   * standing in for a user-chosen tag or category. Passing it also drops the
   * variant's label colour, since the caller's background is unknown and
   * `text-primary-foreground` would be a guess. Pair it with `readableTextColor`
   * when the label has to stay legible on an arbitrary hue.
   */
  backgroundColor?: string | undefined;
  /**
   * Overrides the label's colour, for the same case as `backgroundColor`: with an
   * arbitrary hue behind it, neither the variant's label colour nor the
   * `text-foreground` fallback is guaranteed to be legible. `readableTextColor`
   * is what computes the value to pass.
   */
  textColor?: string | undefined;
  className?: string | undefined;
  /**
   * What the dot stands for, exposed as its accessible name. In the pill form
   * the text is already the name, so there it only feeds `removeLabel`'s default
   * when the children hold no text of their own.
   */
  label?: string | undefined;
  /**
   * Draws a trailing ✕, a button of its own, that calls this — a tag or a filter
   * chip the user can take off. The ✕ is in the label's colour, and pressing it
   * reaches nothing else on the badge. Ignored by the dot, which has no room for
   * it, and by the web half's `asChild`, whose one child is the whole badge.
   */
  onRemove?: (() => void) | undefined;
  /** The ✕'s accessible name. Defaults to `Remove <text>`, the badge's own text. */
  removeLabel?: string | undefined;
  /**
   * The label: text, a number, or elements such as an icon beside text. Absent —
   * including an empty string — collapses the badge to a dot.
   */
  children?: ReactNode;
};

/** Whether `children` holds anything to show, which is what decides pill or dot. */
export function badgeHasLabel(children: ReactNode): boolean {
  return !(children === undefined || children === null || children === false || children === "");
}

/**
 * The ✕'s default name: `Remove` and the badge's text — its string and number
 * children — or `label` when the children are all elements.
 */
export function badgeRemoveLabel(children: ReactNode, label?: string | undefined): string {
  const text = Children.toArray(children)
    .filter((child) => typeof child === "string" || typeof child === "number")
    .join("")
    .trim();
  const name = text || label;
  return name ? `Remove ${name}` : "Remove";
}

/**
 * No `align-self` here: a badge beside a select or a button takes the row's `items-center` like
 * everything else in it. Keeping it from stretching down a column is each half's job — `w-fit`
 * on the web, `self-start` on native, where Yoga has no fit-content.
 *
 * The container: shape and background. `shape` is derived from whether a label
 * was passed, not taken as a prop — a dot is what a badge with nothing to say
 * already is, and making it a second axis would allow the two states that mean
 * nothing: a dot with a label it cannot show, and an empty pill.
 */
export const badgeContainerVariants = cva("shrink-0 rounded-full border border-transparent", {
  variants: {
    variant: {
      default: "bg-primary",
      secondary: "bg-secondary",
      destructive: "bg-destructive",
      outline: "border-border bg-transparent",
      ghost: "bg-transparent",
      link: "bg-transparent",
      success: "bg-green-700",
      warning: "bg-amber-700",
    },
    shape: {
      pill: "flex-row items-center justify-center gap-1 px-2 py-0.5",
      dot: "h-2 w-2",
    },
  },
  defaultVariants: { variant: "default", shape: "pill" },
});

/** The label's colour and nothing else, per variant. */
const BADGE_INK = {
  default: "text-primary-foreground",
  secondary: "text-secondary-foreground",
  destructive: "text-white",
  outline: "text-foreground",
  ghost: "text-foreground",
  link: "text-primary",
  success: "text-white",
  warning: "text-white",
} satisfies Record<BadgeVariant, string>;

/** The label's type and colour, per variant. */
export const badgeTextVariants = cva("text-xs font-medium", {
  variants: {
    variant: { ...BADGE_INK, link: "text-primary underline-offset-4" },
  },
  defaultVariants: { variant: "default" },
});

/**
 * The ✕'s colour on native, where nothing inherits: the label's ink without its
 * type, which an `<Svg>` has no use for. The web ✕ takes `currentColor` instead.
 */
export const badgeInkVariants = cva("", {
  variants: { variant: BADGE_INK },
  defaultVariants: { variant: "default" },
});

/** The label's class when `backgroundColor` replaced the variant's own. */
export const badgeTextFallback = "text-xs font-medium text-foreground";

/** `badgeInkVariants`' counterpart, for when `backgroundColor` replaced the variant's own. */
export const badgeInkFallback = "text-foreground";

/**
 * The badge's icon size — the one the web half gives an `<svg>` child — and so the ✕'s. It is
 * shorter than the label's line, so the ✕ never makes the pill taller.
 */
export const badgeIconClass = "size-3 shrink-0";

/**
 * shadcn's `badgeVariants`: the whole pill's classes, container and label together, for dressing
 * something else — a link, a button — as a badge. The two class maps never touch the same
 * property, so they join without merging.
 */
export function badgeVariants({
  variant,
  shape,
}: {
  variant?: BadgeVariant | null | undefined;
  shape?: "pill" | "dot" | null | undefined;
} = {}): string {
  return `${badgeContainerVariants({ variant, shape })} ${badgeTextVariants({ variant })}`;
}

/**
 * A small pill stating what something is or what state it is in — and, with no
 * label, the dot that stands for the same thing in a row too tight for words.
 * `badge.web.tsx` is the web counterpart and `badge-base.ts` holds the contract
 * and the class maps they share.
 *
 * This is the merge of two vocabularies. It keeps shadcn's variant names with
 * shadcn's meanings, so a DOM call site ports over unchanged and
 * `variant="secondary"` still means what it meant there. It adds `success` and
 * `warning`, which the shadcn token set has no answer for at all: that set
 * carries exactly one semantic colour, `destructive`. The two additions are
 * palette colours chosen to sit beside it rather than tokens, because promoting
 * them to `--success` / `--warning` would put this repo's `:root` block out of
 * step with cubeui's while the two still have to agree. That promotion is a
 * later edit to `tokens/palette.mjs` and the class maps; it does not reach a
 * single call site, which is why it can wait.
 *
 * The two shades are the 700s and not the friendlier 500s or 600s because white
 * on `green-600` is 3.22:1 and white on `amber-500` is 2.13:1 — both short of
 * the 4.5:1 that 12px text needs, and both caught by the axe run behind
 * `stories/accessible-state.stories.tsx` rather than by eye. The 700s clear it
 * at 4.95 and 5.03, which puts them beside `destructive`'s own 4.77. Brightening
 * either one back is what that story exists to stop.
 *
 * **No children collapses the pill into a dot.** Same variant, same meaning,
 * no room needed — a list row that cannot spare the width for "Overdue" shows
 * the amber dot instead, and both come from one prop. This does not overlap
 * `color-dot`: that one takes a literal colour string for a category whose hue
 * is user-chosen data, and this one takes a semantic variant. Same pixels,
 * different input.
 *
 * Colour is split across the container and the `<Text>` for the usual reason:
 * native does not inherit it. So each string or number among the children is
 * wrapped in its own `<Text>` carrying the label class, and an element — an
 * icon — is rendered as it is. shadcn's `asChild` is web only; see `button.tsx`'s
 * header for why it goes the other way round on native.
 *
 * `onRemove` adds a trailing ✕ in its own `Pressable`, so a removable tag is not
 * a second pill the caller draws around this one. The ✕ is the badge's icon
 * size, which is shorter than the label's line, and `hitSlop` is what makes it
 * a reasonable target — padding would make the pill taller. Its colour is the
 * label's, resolved the same way: `textColor`, else the variant's ink.
 */
import { Children } from "react";
import { Pressable, Text, View } from "react-native";
import {
  type BadgeProps,
  type BadgeVariant,
  badgeContainerVariants,
  badgeHasLabel,
  badgeIconClass,
  badgeInkFallback,
  badgeInkVariants,
  badgeRemoveLabel,
  badgeTextFallback,
  badgeTextVariants,
  badgeVariants,
} from "@/components/ui/badge-base";
import { X } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

/** A 12px glyph grown to about 28 by 28 of touch, without growing the pill. */
const REMOVE_HIT_SLOP = { top: 8, bottom: 8, left: 6, right: 8 } as const;

export type { BadgeProps, BadgeVariant };

export function Badge({
  variant = "default",
  backgroundColor,
  textColor,
  className,
  label,
  onRemove,
  removeLabel,
  children,
}: BadgeProps) {
  const shape = badgeHasLabel(children) ? "pill" : "dot";
  const textClass = backgroundColor ? badgeTextFallback : badgeTextVariants({ variant });
  const inkClass = backgroundColor ? badgeInkFallback : badgeInkVariants({ variant });

  return (
    <View
      // Yoga stretches a child across a column and has no fit-content to stop it, so on native the
      // badge pins itself to the start. In a centred row, pass `className="self-center"`.
      className={cn("self-start", badgeContainerVariants({ variant, shape }), className)}
      {...(backgroundColor ? { style: { backgroundColor } } : {})}
      // A dot carries meaning and no text, so it is named or it is decoration;
      // the same split `color-dot` makes, for the same reason.
      {...(shape === "dot"
        ? label
          ? ({ role: "img", "aria-label": label } as const)
          : ({ "aria-hidden": true } as const)
        : {})}
    >
      {shape === "pill"
        ? Children.map(children, (child) =>
            typeof child === "string" || typeof child === "number" ? (
              <Text className={textClass} {...(textColor ? { style: { color: textColor } } : {})}>
                {child}
              </Text>
            ) : (
              child
            ),
          )
        : null}
      {shape === "pill" && onRemove ? (
        <Pressable
          onPress={onRemove}
          // The `role` is hand-written because a `<button>` has no native counterpart.
          role="button"
          aria-label={removeLabel ?? badgeRemoveLabel(children, label)}
          hitSlop={REMOVE_HIT_SLOP}
        >
          <X
            className={cn(badgeIconClass, inkClass)}
            // An inline prop wins over the colour the class maps to, as `style` does on the `Text`.
            {...(textColor ? { color: textColor } : {})}
          />
        </Pressable>
      ) : null}
    </View>
  );
}

export { badgeVariants };

/**
 * The web badge: one `<span>`, as shadcn's is. `badge.tsx` is the native
 * counterpart, and its header has the reasoning behind the variants and the dot;
 * `badge-base.ts` holds the contract and the class maps they share.
 *
 * On the DOM, colour inherits, so the label class sits on the container and the
 * children — text, a number, an icon beside text — render straight inside it.
 * It also takes every `<span>` attribute (`style`, `title`, `onClick`, `data-*`)
 * and shadcn's `asChild`, which hands the classes to the single child — a link
 * dressed as a badge. Those extras are web only.
 *
 * `onRemove` adds a trailing ✕ as a `<button type="button">`, so it never
 * submits a form it sits in, and its click stops at the button so a badge's own
 * `onClick` does not fire under it. The glyph is `currentColor`, so it follows
 * the label through `textColor`, a variant or a hover. Its padding is the hit
 * area and a negative margin of the same size takes it back out of the layout,
 * which keeps the pill the height it was; it stays inside the pill's edge
 * because `overflow-hidden` would clip a target that did not.
 */
import { Slot } from "radix-ui";
import type * as React from "react";
import {
  type BadgeProps,
  type BadgeVariant,
  badgeContainerVariants,
  badgeHasLabel,
  badgeIconClass,
  badgeRemoveLabel,
  badgeTextFallback,
  badgeTextVariants,
  badgeVariants,
} from "@/components/ui/badge-base";
import { X } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

export type { BadgeProps, BadgeVariant };

export function Badge({
  variant = "default",
  backgroundColor,
  textColor,
  className,
  label,
  onRemove,
  removeLabel,
  asChild = false,
  style,
  children,
  ...props
}: BadgeProps &
  Omit<React.ComponentProps<"span">, keyof BadgeProps> & {
    /** Render the single child with the badge's classes instead of a `<span>`. */
    asChild?: boolean | undefined;
  }) {
  const shape = asChild || badgeHasLabel(children) ? "pill" : "dot";
  const Comp = asChild ? Slot.Root : "span";

  return (
    <Comp
      data-slot="badge"
      data-variant={variant}
      className={cn(
        "inline-flex w-fit overflow-hidden whitespace-nowrap transition-[color,box-shadow] focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 [&>svg]:pointer-events-none [&>svg]:size-3",
        badgeContainerVariants({ variant, shape }),
        shape === "pill" && (backgroundColor ? badgeTextFallback : badgeTextVariants({ variant })),
        variant === "link" && "[a&]:hover:underline",
        className,
      )}
      style={{
        ...(backgroundColor ? { backgroundColor } : {}),
        ...(textColor ? { color: textColor } : {}),
        ...style,
      }}
      // A dot carries meaning and no text, so it is named or it is decoration;
      // the same split `color-dot` makes, for the same reason.
      {...(shape === "dot"
        ? label
          ? ({ role: "img", "aria-label": label } as const)
          : ({ "aria-hidden": true } as const)
        : {})}
      {...props}
    >
      {shape === "pill" ? children : null}
      {shape === "pill" && onRemove && !asChild ? (
        <button
          type="button"
          aria-label={removeLabel ?? badgeRemoveLabel(children, label)}
          className="-my-1 -mr-1.5 -ml-1 inline-flex cursor-pointer items-center justify-center rounded-full p-1 text-inherit outline-none hover:opacity-75 focus-visible:ring-2 focus-visible:ring-current focus-visible:ring-inset"
          onClick={(event) => {
            event.stopPropagation();
            onRemove();
          }}
          // The keys that press it, stopped too, so a badge's own `onKeyDown` does not act on them.
          onKeyDown={(event) => {
            if (event.key === "Enter" || event.key === " ") event.stopPropagation();
          }}
        >
          <X className={badgeIconClass} aria-hidden />
        </button>
      ) : null}
    </Comp>
  );
}

export { badgeVariants };
